  1	/**
  2	 * Route Table Structure Tests
  3	 *
  4	 * WP-005: Validates the structural invariants of the unified route table
  5	 * returned by `buildRoutes()` in gui/server.ts to prevent regressions when
  6	 * adding future routes.
  7	 *
  8	 * Invariants verified:
  9	 *  1. Every route entry has a `method` value from the set {GET, POST, PUT, PATCH, DELETE}.
 10	 *  2. Every RegExp route uses only named capture groups — no positional (unnamed) groups.
 11	 *  3. No two routes share the same `method + path` combination (exact string or RegExp source).
 12	 */
 13	
 14	import { describe, it, expect } from 'vitest';
 15	
 16	import { getRouteDescriptors, HttpMethod } from '../../gui/server.js';
 17	
 18	// ---------------------------------------------------------------------------
 19	// Fixture: route table obtained via the zero-argument factory — no dummy args
 20	// ---------------------------------------------------------------------------
 21	
 22	const routes = getRouteDescriptors();
 23	
 24	// ---------------------------------------------------------------------------
 25	// Helper: extract the "path key" used for duplicate detection
 26	// ---------------------------------------------------------------------------
 27	
 28	function pathKey(path: string | RegExp): string {
 29	  return typeof path === 'string' ? path : path.source;
 30	}
 31	
 32	// ---------------------------------------------------------------------------
 33	// Tests
 34	// ---------------------------------------------------------------------------
 35	
 36	describe('buildRoutes() — route table structural invariants', () => {
 37	
 38	  it('returns a non-empty array', () => {
 39	    expect(Array.isArray(routes)).toBe(true);
 40	    expect(routes.length).toBeGreaterThan(0);
 41	  });
 42	
 43	  it('every route has a valid HTTP method (GET, POST, PUT, PATCH, DELETE)', () => {
 44	    // The HttpMethod union type in server.ts enforces this constraint at compile
 45	    // time. This runtime test serves as defense-in-depth — it guards against
 46	    // future changes that might accidentally widen the type or cast around it.
 47	    const VALID_METHODS = new Set<HttpMethod>(['GET', 'POST', 'PUT', 'PATCH', 'DELETE']);
 48	
 49	    const violations = routes.filter(
 50	      (route) => !VALID_METHODS.has(route.method),
 51	    );
 52	
 53	    expect(violations).toEqual([]);
 54	  });
 55	
 56	  it('every RegExp route uses only named capture groups — no positional (unnamed) groups', () => {
 57	    /**
 58	     * A positional (unnamed) capture group is an opening parenthesis `(` that is
 59	     * NOT followed by either:
 60	     *   - `?:` — non-capturing group
 61	     *   - `?<` — named capture group
 62	     *   - `?=` — positive lookahead
 63	     *   - `?!` — negative lookahead
 64	     *   - `?<=` — positive lookbehind
 65	     *   - `?<!` — negative lookbehind
 66	     *
 67	     * The regex below detects any `(` that does NOT start one of the above
 68	     * special-group syntaxes (i.e., it is a plain capturing group).
 69	     */
 70	    const POSITIONAL_GROUP_RE = /\((?!\?)/;
 71	
 72	    const violations = routes.filter((route) => {
 73	      if (typeof route.path !== 'object') return false;   // skip string routes
 74	      return POSITIONAL_GROUP_RE.test(route.path.source);
 75	    });
 76	
 77	    const violatingPatterns = violations.map((r) => ({
 78	      method: r.method,
 79	      source: (r.path as RegExp).source,
 80	    }));
 81	
 82	    expect(violatingPatterns).toEqual([]);
 83	  });
 84	
 85	  it('no two routes share the same method + path combination', () => {
 86	    const seen = new Map<string, number>();   // key → first index
 87	    const duplicates: Array<{ index: number; method: string; path: string }> = [];
 88	
 89	    routes.forEach((route, idx) => {
 90	      const key = `${route.method} ${pathKey(route.path)}`;
 91	      if (seen.has(key)) {
 92	        duplicates.push({ index: idx, method: route.method, path: pathKey(route.path) });
 93	      } else {
 94	        seen.set(key, idx);
 95	      }
 96	    });
 97	
 98	    expect(duplicates).toEqual([]);
 99	  });
100

101	  const idx = args.indexOf('--port');
102	  if (idx !== -1 && idx + 1 < args.length) {
103	    const p = parseInt(args[idx + 1]!, 10);
104	    if (!isNaN(p) && p > 0) return p;
105	  }
106	  return 3420;
107	}
108	
109	// ---------------------------------------------------------------------------
110	// MIME types
111	// ---------------------------------------------------------------------------
112	
113	const MIME_TYPES: Record<string, string> = {
114	  '.html': 'text/html',
115	  '.css': 'text/css',
116	  '.js': 'application/javascript',
117	};
118	
119	// ---------------------------------------------------------------------------
120	// CORS helpers
121	// ---------------------------------------------------------------------------
122	
123	function corsHeaders(port: number): Record<string, string> {
124	  return {
125	    'Access-Control-Allow-Origin': `http://localhost:${port}`,
126	    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
127	    'Access-Control-Allow-Headers': 'Content-Type',
128	  };
129	}
130	
131	// ---------------------------------------------------------------------------
132	// Security headers
133	// ---------------------------------------------------------------------------
134	
135	function securityHeaders(): Record<string, string> {
136	  return {
137	    'X-Content-Type-Options': 'nosniff',
138	    'X-Frame-Options': 'DENY',
139	    'Referrer-Policy': 'strict-origin-when-cross-origin',
140	    'Content-Security-Policy':
141	      "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'",
142	  };
143	}
144	
145	// ---------------------------------------------------------------------------
146	// Response helpers
147	// ---------------------------------------------------------------------------
148	
149	function sendJson(
150	  res: ServerResponse,
151	  status: number,
152	  data: unknown,
153	  port: number
154	): void {
155	  const body = JSON.stringify(data);
156	  res.writeHead(status, {
157	    'Content-Type': 'application/json',
158	    'Content-Length': Buffer.byteLength(body),
159	    ...corsHeaders(port),
160	    ...securityHeaders(),
161	  });
162	  res.end(body);
163	}
164	
165	function sendError(
166	  res: ServerResponse,
167	  status: number,
168	  code: string,
169	  message: string,
170	  port: number
171	): void {
172	  sendJson(res, status, { error: { code, message } }, port);
173	}
174	
175	export function apiErrorToStatus(code: string): number {
176	  switch (code) {
177	    case 'NOT_FOUND':
178	      return 404;
179	    case 'FORBIDDEN':
180	      return 403;
181	    case 'VALIDATION_ERROR':
182	      return 400;
183	    case 'CONFLICT':
184	      return 409;
185	    default:
186	      return 500;
187	  }
188	}
189	
190	// ---------------------------------------------------------------------------
191	// Body reading
192	// ---------------------------------------------------------------------------
193	
194	/** Maximum accepted request body size (1 MiB). */
195	export const MAX_BODY_BYTES = 1_048_576;
196	
197	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
198	export class PayloadTooLargeError extends Error {
199	  constructor() {
200	    super('Payload Too Large');
201	    this.name = 'PayloadTooLargeError';
202	  }
203	}
204	
205	/**
206	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
207	 * {@link MAX_BODY_BYTES} (1 MiB).
208	 *
209	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
210	 *   either via Content-Length header pre-check or streaming byte count).
211	 *   **Callers must catch this error and return a 413 response.**
212	 *
213	 * @param req - The incoming HTTP request.
214	 * @returns The full body string.
215	 */
216	function readBody(req: IncomingMessage): Promise<string> {
217	  return new Promise((resolve, reject) => {
218	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
219	    const declaredLength = req.headers['content-length'];
220	    if (declaredLength !== undefined) {
221	      const n = parseInt(declaredLength, 10);
222	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
223	        req.resume();  // drain body data from socket buffer
224	        reject(new PayloadTooLargeError());
225	        return;
226	      }
227	    }
228	
229	    const chunks: Buffer[] = [];
230	    let totalBytes = 0;
231	    let rejected = false;
232	
233	    req.on('data', (chunk: Buffer) => {
234	      if (rejected) return;
235	      totalBytes += chunk.length;
236	      if (totalBytes > MAX_BODY_BYTES) {
237	        rejected = true;
238	        reject(new PayloadTooLargeError());
239	        // Drain remaining data so the 413 response can be sent cleanly.
240	        req.resume();
241	        return;
242	      }
243	      chunks.push(chunk);
244	    });
245	    req.on('end', () => {
246	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
247	    });
248	    req.on('error', (err) => {
249	      if (!rejected) reject(err);
250	    });

251	  });
252	}
253	
254	/**
255	 * Reads and parses the request body as JSON, enforcing the same size limit as
256	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
257	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
258	 *
259	 * @param req - The incoming HTTP request.
260	 * @returns The parsed JSON value.
261	 */
262	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
263	  const raw = await readBody(req);
264	  try {
265	    return JSON.parse(raw);
266	  } catch {
267	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
268	  }
269	}
270	
271	// ---------------------------------------------------------------------------
272	// Router
273	// ---------------------------------------------------------------------------
274	
275	/**
276	 * The set of HTTP methods accepted by the route dispatcher.
277	 *
278	 * Narrowing `Route.method` to this union converts a previously runtime-only
279	 * validation (enforced by `route-table.test.ts`) into a compile-time guarantee.
280	 * The test continues to serve as defense-in-depth.
281	 */
282	export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
283	
284	/**
285	 * A declarative body-parsing route entry for {@link buildRoutes} and
286	 * {@link dispatchRoute}.
287	 *
288	 * - `method` — HTTP method; must be one of the {@link HttpMethod} values
289	 *   (`GET`, `POST`, `PUT`, `PATCH`, `DELETE`, uppercase). The union type
290	 *   enforces this at compile time; `route-table.test.ts` provides
291	 *   defense-in-depth at test time.
292	 * - `path` — Exact string path or a RegExp with named capture groups.
293	 * - `handler` — Receives the parsed body (or `undefined` when `noBody` is
294	 *   set), any named capture groups extracted from the RegExp match, and the
295	 *   parsed query parameters from the request URL.
296	 * - `statusCode` — Response status code (default `200`). Use `204` for empty
297	 *   responses — the dispatcher writes the header and skips `sendJson()`.
298	 * - `noBody` — When `true`, skip `readJsonBody()`.
299	 */
300	export interface Route {
301	  method: HttpMethod;
302	  path: string | RegExp;
303	  handler: (body: unknown, groups?: Record<string, string>, query?: URLSearchParams) => Promise<unknown>;
304	  statusCode?: number;
305	  noBody?: boolean;
306	}
307	
308	// ---------------------------------------------------------------------------
309	// Meta helpers
310	// ---------------------------------------------------------------------------
311	
312	/**
313	 * Guards against path-traversal attacks on URL parameters that are used as
314	 * filesystem path segments.
315	 *
316	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
317	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
318	 * callers receive the same status as a missing project — no information leak.
319	 *
320	 * @param segment - The raw URL parameter value to validate.
321	 */
322	function assertSafeSlug(segment: string): void {
323	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
324	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
325	  }
326	}
327	
328	/**
329	 * Reads the `.meta.json` for a namespaced project at
330	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
331	 *
332	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
333	 * when the field is absent or null.
334	 *
335	 * When the meta file exists but contains malformed JSON, the function still
336	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
337	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
338	 * to URL param '…'`) so operators can detect corrupt meta files during
339	 * troubleshooting. API callers always receive the fallback value in this case.
340	 *
341	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
342	 * indicating that the `{repo}/{slug}` combination is not a known project in
343	 * this ledger. This is the project-existence check for namespaced routes.
344	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
345	 * information-hiding: invalid-input and missing-project cases are
346	 * indistinguishable from the client side.
347	 *
348	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
349	 * before any filesystem access is attempted (defence-in-depth).
350	 */
351	export async function resolveRepoName(
352	  ledgerRoot: string,
353	  repoUrlParam: string,
354	  slugUrlParam: string,
355	): Promise<string> {
356	  assertSafeSlug(repoUrlParam);
357	  assertSafeSlug(slugUrlParam);
358	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
359	  let raw: string;
360	  try {
361	    raw = await readFile(metaPath, 'utf-8');
362	  } catch {
363	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
364	  }
365	  try {
366	    const meta = JSON.parse(raw) as { repository_name?: string | null };
367	    return meta.repository_name ?? repoUrlParam;
368	  } catch {
369	    // Malformed .meta.json — project directory exists, fall back to URL param.
370	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
371	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
372	    return repoUrlParam;
373	  }
374	}
375	
376	/**
377	 * Extracts query-string parameters from a full URL string.
378	 * Returns a URLSearchParams instance (empty if no query string present).
379	 *
380	 * Edge-case behaviour:
381	 * - **Bare `?`** (e.g. `/api/foo?`): `url.slice(qIdx + 1)` is `""` → returns
382	 *   an empty `URLSearchParams`. Safe, no exceptions.
383	 * - **Percent-encoded values** (e.g. `?q=hello%20world`): `URLSearchParams`
384	 *   decodes them transparently — `params.get('q')` returns `"hello world"`.
385	 * - **Fragment / hash characters** (e.g. `?x=1#anchor`): the `#` and
386	 *   everything after it are passed through as literal characters inside the
387	 *   query value because no fragment stripping is performed. Browsers strip the
388	 *   fragment before sending the request, so in practice this situation does not
389	 *   arise for server-received URLs.
390	 */
391	function parseQueryString(url: string): URLSearchParams {
392	  const qIdx = url.indexOf('?');
393	  return new URLSearchParams(qIdx !== -1 ? url.slice(qIdx + 1) : '');
394	}
