396	// ---------------------------------------------------------------------------
397	// Static file server
398	// ---------------------------------------------------------------------------
399	
400	async function serveStatic(
401	  req: IncomingMessage,
402	  res: ServerResponse,
403	  port: number
404	): Promise<void> {
405	  const urlPath = (req.url ?? '/').split('?')[0]!;
406	  const filePath =
407	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
408	
409	  // Security: prevent path traversal outside PUBLIC_DIR
410	  const resolved = resolve(filePath);
411	  if (!resolved.startsWith(PUBLIC_DIR)) {
412	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
413	    return;
414	  }
415	
416	  const ext = extname(filePath);
417	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
418	
419	  try {
420	    const content = await readFile(filePath);
421	    res.writeHead(200, {
422	      'Content-Type': mimeType,
423	      'Content-Length': content.length,
424	      'Cache-Control': 'no-store',
425	      ...corsHeaders(port),
426	      ...securityHeaders(),
427	    });
428	    res.end(content);
429	  } catch {
430	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
431	  }
432	}
