1172	/**
1173	 * Builds the declarative route table consumed by {@link dispatchRoute}.
1174	 *
1175	 * All closure variables required by route handlers (`ledgerRoot`, `configPath`,
1176	 * `orchestratorLogsDir`, `bootVersions`) are captured via the domain sub-builder
1177	 * functions. Each sub-builder owns a single domain area and accepts only the
1178	 * closure parameters it needs:
1179	 *
1180	 *   - {@link buildConfigRoutes}      — `PUT/GET /api/config`, `GET /api/server-info`
1181	 *   - {@link buildOrchestratorRoutes} — `/api/orchestrator/*`
1182	 *   - {@link buildRepoRoutes}         — `/api/repos/*`
1183	 *   - {@link buildKnowledgeRoutes}    — `/api/knowledge/*`
1184	 *   - {@link buildModelRoutes}        — `/api/models/*`, `/api/model-assignments/*`, `/api/personas/*`
1185	 *   - {@link buildProjectRoutes}      — `/api/projects/*`, `/api/insights`
1186	 *
1187	 * The composed array preserves the Section A/B/C ordering invariant:
1188	 *
1189	 *   Section A — Body-parsing routes (no `noBody` flag). Sub-builders place their
1190	 *               Section A entries first; buildRoutes spreads them in domain order.
1191	 *
1192	 *   Section B — Keyword-specific body-free routes (`noBody: true`). Routes with
1193	 *               a fixed keyword suffix (e.g. `/plan`, `/archive`) are more specific
1194	 *               than the Section C catch-alls and MUST precede them.
1195	 *
1196	 *   Section C — Catch-all body-free routes. These are placed last by
1197	 *               {@link buildProjectRoutes} and are spread last.
1198	 *
1199	 * ⚠️  ORDERING CONSTRAINT (load-bearing, not cosmetic):
1200	 *     Section B MUST precede Section C across all sub-builders. The dispatcher
1201	 *     walks the table in declaration order and returns on the first match. A
1202	 *     Section C catch-all such as `GET /api/projects/:repo/:slug` would silently
1203	 *     shadow all deprecated Section B keyword routes (`/:slug/plan`,
1204	 *     `/:slug/synthesis`, etc.) if they were declared before them, permanently
1205	 *     breaking backward compatibility with pre-namespace clients.
1206	 */
1207	export function buildRoutes(
1208	  ledgerRoot: string,
1209	  configPath: string,
1210	  orchestratorLogsDir: string,
1211	  bootVersions: WorkspaceVersions | null
1212	): Route[] {
1213	  return [
1214	    ...buildConfigRoutes(configPath, bootVersions),
1215	    ...buildOrchestratorRoutes(ledgerRoot, orchestratorLogsDir),
1216	    ...buildRepoRoutes(ledgerRoot),
1217	    ...buildKnowledgeRoutes(ledgerRoot),
1218	    ...buildModelRoutes(),
1219	    ...buildProjectRoutes(ledgerRoot, orchestratorLogsDir),
1220	  ];
1221	}
