1223	/**
1224	 * Returns the full route table using sentinel dummy arguments, without
1225	 * requiring callers to supply real filesystem paths.
1226	 *
1227	 * Intended for structural tests (e.g. `route-table.test.ts`) that inspect the
1228	 * route table shape — method validity, named-capture-group compliance,
1229	 * duplicate detection — without executing any handlers.
1230	 *
1231	 * Uses `/dev/null` as a safe sentinel for all path arguments and `null` for
1232	 * `bootVersions`. The handlers captured inside each route are closures over
1233	 * these sentinels; as long as no handler is actually invoked the sentinels have
1234	 * no observable effect.
1235	 *
1236	 * @returns The full `Route[]` table, identical in structure to what
1237	 *   {@link handleRequest} uses at runtime.
1238	 */
1239	export function getRouteDescriptors(): Route[] {
1240	  return buildRoutes('/dev/null', '/dev/null', '/dev/null', null);
1241	}
